                if (value.session_id == null) throw new Exception("Invalid RunUiTestReply.session_id");
                if (value.steps == null) throw new Exception("Invalid RunUiTestReply.steps");
                if (value.test_instance_id == null) throw new Exception("Invalid RunUiTestReply.test_instance_id");
            }
        }

