            if (value.character_count < 0) throw new Exception("Invalid CreateTmpFontReply.character_count");
            if (value.ok == true)
            {
                if (value.asset_path == null || value.asset_path == null || (value.asset_path == null || value.asset_path.Length < 1)) throw new Exception("Invalid CreateTmpFontReply.asset_path");
                if (value.guid == null || value.guid == null || (value.guid == null || value.guid.Length < 1)) throw new Exception("Invalid CreateTmpFontReply.guid");
                if (value.missing_codepoints == null) throw new Exception("Invalid CreateTmpFontReply.missing_codepoints");
                if (value.population_mode == null || value.population_mode == null || (value.population_mode != "static" && value.population_mode != "dynamic")) throw new Exception("Invalid CreateTmpFontReply.population_mode");
            }
            if (value.ok == false)
            {
                if (value.error == null || value.error == null || (value.error == null || value.error.Length < 1)) throw new Exception("Invalid CreateTmpFontReply.error");
            }
        }

